lore_template:
{{#if (eq type "npc")}}
<npc name="{{name}}"{{#if labels}} labels="{{labels}}"{{/if}}>
{{content}}
{{#if npc_info}}
{{npc_info}}
{{/if}}
{{#if rpg_stats}}
<stats>{{rpg_stats}}</stats>
{{/if}}
</npc>
{{else}}{{#if (eq type "location")}}
<location name="{{name}}">
{{content}}
</location>
{{else}}{{#if (eq type "item")}}
<item name="{{name}}">
{{content}}
{{#if item_config}}{{item_config}}{{/if}}
</item>
{{else}}{{#if (eq type "creature")}}
<creature name="{{name}}"{{#if labels}} labels="{{labels}}"{{/if}}>
{{content}}
{{#if creature_config}}{{creature_config}}{{/if}}
{{#if rpg_stats}}
<stats>{{rpg_stats}}</stats>
{{/if}}
</creature>
{{else}}{{#if (eq type "event")}}
<event name="{{name}}">
{{content}}
</event>
{{else}}
<lore name="{{name}}"{{#if type}} type="{{type}}"{{/if}}>
{{content}}
</lore>
{{/if}}{{/if}}{{/if}}{{/if}}{{/if}}
